    static class Json {
        String s; int p;
        Json(String s) { this.s = s; }
        void space() { while(p<s.length() && Character.isWhitespace(s.charAt(p))) p++; }
        Object value() {
            space(); char c=s.charAt(p);
            if(c=='{') { p++; Map<String,Object> m=new LinkedHashMap<>(); space();
                while(s.charAt(p)!='}') { String k=(String)value(); space(); p++; m.put(k,value()); space(); if(s.charAt(p)==',')p++; else break; } p++; return m; }
            if(c=='[') { p++; List<Object> a=new ArrayList<>(); space();
                while(s.charAt(p)!=']') { a.add(value()); space(); if(s.charAt(p)==',')p++; else break; } p++; return a; }
            if(c=='"') { p++; StringBuilder b=new StringBuilder(); while(s.charAt(p)!='"') { char x=s.charAt(p++);
                if(x=='\\') { char e=s.charAt(p++); x=switch(e) {case 'n'->'\n'; case 'r'->'\r'; case 't'->'\t'; default->e;}; } b.append(x); } p++; return b.toString(); }
            if(s.startsWith("true",p)) {p+=4;return true;} if(s.startsWith("false",p)){p+=5;return false;} if(s.startsWith("null",p)){p+=4;return null;}
            int st=p; while(p<s.length() && "-+0123456789.eE".indexOf(s.charAt(p))>=0)p++; return Double.valueOf(s.substring(st,p));
        }
        static String stringify(Object o) {
            if(o==null)return "null";
            if(o instanceof String v)return "\""+v.replace("\\","\\\\").replace("\"","\\\"").replace("\n","\\n")+"\"";
            if(o instanceof Number || o instanceof Boolean)return o.toString();
            List<String> a=new ArrayList<>();
            if(o.getClass().isArray()) { for(int i=0;i<java.lang.reflect.Array.getLength(o);i++)a.add(stringify(java.lang.reflect.Array.get(o,i))); }
            else if(o instanceof Iterable<?> v) { for(Object x:v)a.add(stringify(x)); }
            else throw new IllegalArgumentException("返回类型需要可JSON序列化");
            return "["+String.join(",",a)+"]";
        }
    }
